python -I -c 'import glob,numpy as np,collections
c=collections.Counter(); by=collections.defaultdict(list)
for f in glob.glob("/workspace/results/token_records/*.npz"):
 d=np.load(f); lens=d["mask"].sum(1); adv=d["advantages"]
 for n,a in zip(lens,adv):
  trunc=int(n)==256; sign="pos" if a>0 else "neg" if a<0 else "zero"
  c[(sign,trunc)]+=1
  if a!=0: by[sign].append(int(n))
print("all 96 rows (advantage sign, length==256):",dict(c))
for k,v in by.items(): print(k,"count",len(v),"truncated",sum(x==256 for x in v),"length_mean",np.mean(v),"lengths",sorted(v))'

